INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `Text_lang`, `Text1_lang`, `VerifiedBuild`) VALUES
(121462, 'ruRU', '', 'Оставь меня в покое. Я работаю. В толпе могут быть враги.', 24330),
(121463, 'ruRU', '', 'Мы не можем терять надежду, $ct. Если нам как-то удастся победить Легион, потребуется новое поколение шаманов, чтобы исцелить этот опалённый мир.', 24330),
(121464, 'ruRU', '', 'Разве я похожа на ту, что хочет умереть? Ещё раз, я имею в виду?$b$bЕсли тебя интересует облик Насылающего Погибель, можешь спросить его самого. Или Тёмную Госпожу, если на то пошло. Они оба так любят светскую беседу.$b$b<Тёмный рейнджер усмехается, возвращаясь к своему дозору.>', 24330),
(121469, 'ruRU', '', 'Стихия воды олицетворяет безмятежность и обновление. Но нам нужно быть осторожными, ведь водные духи могут быть весьма капризны.', 24330),
(121470, 'ruRU', '', 'Если ты можешь говорить с ветрами, ты можешь слышать вести издалека. При достаточном контроле шаман также может обуздать ярость грозы.', 24330),
(121471, 'ruRU', '', 'Подмастерье Золотая Жила тоже когда-то была моей ученицей. Но пусть это тебя не смущает.', 24330),
(121472, 'ruRU', '', 'Земля укореняет нас во всём. Если мы едины с землёй, мы станем для наших врагов неприступны, как гора.', 24330),
(121473, 'ruRU', '', 'Большинство связывают стихию огня с разрушением, но в бережных руках огонь может готовить нашу еду или согревать наши дома. Ученики, как вы используете огонь?', 24330),
(121504, 'ruRU', '', 'Мы заставим Легион заплатить за то, что они сделали!', 24330),
(121510, 'ruRU', '', 'Глупец! Ты думаешь, что добьёшься успеха там, где потерпел неудачу даже я, избранник Саргераса?', 24330),
(121511, 'ruRU', '', 'Все, кто пытался укротить Улталеш, были поглощены. Тебе повезёт не больше!', 24330),
(121512, 'ruRU', '', 'Улталеш поглотит тебя!', 24330),
(121514, 'ruRU', '', 'Ты присоединишься к собранному урожаю!', 24330),
(121515, 'ruRU', '', 'Улталеш пирует!', 24330),
(121516, 'ruRU', '', 'Невозможно... ты будешь... поглощён...', 24330),
(121544, 'ruRU', '', 'Приветствую, $n. Я несу важное послание от Одина!', 24330),
(121545, 'ruRU', '', 'Один ожидает твоего прибытия. Его силы готовы!', 24330),
(121546, 'ruRU', '', '$n. Вот ты где. Мне нужно кое-что тебе сказать.', 24330),
(121547, 'ruRU', '', 'Военачальник Гардун сказал, что это дело чрезвычайной важности.', 24330),
(121548, 'ruRU', '', 'Он попросил, чтобы ты вернулся на Демонический Молот как можно скорее.', 24330),
(121552, 'ruRU', '', 'Псст, $n. Подойди ближе, мне нужно кое-что тебе сказать.', 24330),
(121555, 'ruRU', '', 'Лорду Воронья Крепость нужно обсудить с тобой что-то важное.', 24330),
(121559, 'ruRU', '', 'Он просит, чтобы ты немедленно вернулся в Зал Теней.', 24330),
(121570, 'ruRU', '', 'Я лечу раны, а не глупости...', 24330),
(121577, 'ruRU', '', 'Мастерство моих учеников тебя поразит!', 24330),
(121584, 'ruRU', '', 'Верховный лорд, минуту вашего времени, прошу.', 24330),
(121585, 'ruRU', '', 'Мы с нетерпением ждём твоего возвращения в часовню Последней Надежды.', 24330),
(121595, 'ruRU', '', 'Что?!', 24330),
(121604, 'ruRU', '', 'Интересно, кто это нарисовал? Это потрясающе!', 24330),
(121605, 'ruRU', '', 'Я должен заполучить это, детали выдающиеся!', 24330),
(121606, 'ruRU', '', 'Это произведение просто изысканно.', 24330),
(121607, 'ruRU', '', '<Получить Искривление пространства за 10 |TINTERFACE\\ICONS\\INV_MISC_ANCIENT_MANA.BLP:20|t Древней маны.>', 24330),
(121608, 'ruRU', '', 'Случайность? Тебе не кажется поразительным, что каждое найденное тело украшено рассветной лилией? Тем же цветком, что так любит Талисра?', 24330),
(121611, 'ruRU', '', 'Ты почти на месте, чужак. Окулет должен ждать тебя на другой стороне этой камеры.', 24330),
(121612, 'ruRU', '', 'Ещё раз прошу тебя отвести иссохших в Фаланаар. Научи их сражаться и искать реликвии, что помогут нашему делу.', 24330),
(121637, 'ruRU', '', 'Это... ты... Я видел тебя во сне, преследуемого тенями. Я пробудился лишь для того, чтобы обнаружить, как эти тени проникают в наш мир.', 24330),
(121646, 'ruRU', '', '<Получить Мастерство лей-линий за 50 |TINTERFACE\\ICONS\\INV_MISC_ANCIENT_MANA.BLP:20|t Древней маны.>', 24330),
(121647, 'ruRU', '', '<Получить Мастерство лей-линий за 40 |TINTERFACE\\ICONS\\INV_MISC_ANCIENT_MANA.BLP:20|t Древней маны.>', 24330),
(121648, 'ruRU', '', '<Получить Мастерство лей-линий за 30 |TINTERFACE\\ICONS\\INV_MISC_ANCIENT_MANA.BLP:20|t Древней маны.>', 24330),
(121649, 'ruRU', '', '<Получить Мастерство лей-линий за 20 |TINTERFACE\\ICONS\\INV_MISC_ANCIENT_MANA.BLP:20|t Древней маны.>', 24330);
